"use client";

import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";
import { formatDate } from "@/lib/time";

interface AccountActivityProps {
  user: TUser;
}

export const AccountActivity = ({ user }: AccountActivityProps) => {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <span className="text-sm text-slate-600">{t("workspace.settings.profile.account_created")}</span>
        <span className="text-sm font-medium text-slate-800">
          {formatDate(user.createdAt, user.locale)}
        </span>
      </div>
      <div className="flex items-center justify-between">
        <span className="text-sm text-slate-600">{t("workspace.settings.profile.last_login")}</span>
        <span className="text-sm font-medium text-slate-800">
          {user.lastLoginAt ? formatDate(user.lastLoginAt, user.locale) : t("workspace.settings.profile.never_logged_in")}
        </span>
      </div>
    </div>
  );
};

"use client";

import { useTranslation } from "react-i18next";
import { Button } from "@/modules/ui/components/button";

export const DownloadMyData = () => {
  const { t } = useTranslation();

  const handleDownload = async () => {
    try {
      const response = await fetch("/api/account/download");
      if (!response.ok) {
        return;
      }
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `formbricks-data-${new Date().toISOString().split("T")[0]}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch {
      // Silently fail — user can retry
    }
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload}>
      {t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};

